using Umbraco.Bench.Umbraco.Models;
using Umbraco.Bench.Umbraco.Models.Blog;
using Umbraco.Cms.Core.Models.PublishedContent;
using Umbraco.Extensions;

namespace Umbraco.Bench.Umbraco.Services;

public class BlogPostService
{
    // Posts beneath the blog front page that contains (or is) the given page, newest first.
    public IReadOnlyList<BlogPostSummaryModel> GetPosts(IPublishedContent? currentPage)
    {
        var frontPage = currentPage?.AncestorOrSelf<BlogFrontPage>();
        if (frontPage is null)
        {
            return [];
        }

        return frontPage.Children<BlogPost>()
            .OrderByDescending(post => post.PublishDate)
            .Select(post => new BlogPostSummaryModel
            {
                Title = post.Name,
                Url = post.Url(),
                PublishDate = post.PublishDate,
                TeaserText = post.TeaserText,
                ImageUrl = post.TeaserImage?.GetCropUrl(width: 800, height: 450),
                ImageAlt = post.TeaserImage?.Name,
            })
            .ToList();
    }
}
EOF

