@model Umbraco.Bench.Umbraco.Models.Blocks.BlogPostListModel

<section>
    @if (!string.IsNullOrEmpty(Model.Heading))
    {
        <h2 class="text-3xl font-bold tracking-tight text-slate-900">@Model.Heading</h2>
    }
    @if (!string.IsNullOrEmpty(Model.Intro))
    {
        <p class="mt-2 max-w-2xl text-lg text-slate-600">@Model.Intro</p>
    }

    @if (Model.Posts.Count == 0)
    {
        <p class="mt-8 text-slate-500">No posts yet.</p>
    }
    else
    {
        <div class="mt-10 grid gap-8 md:grid-cols-2">
            @foreach (var post in Model.Posts)
            {
                <article class="group flex flex-col overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200 transition hover:shadow-lg">
                    @if (!string.IsNullOrEmpty(post.ImageUrl))
                    {
                        <a href="@post.Url" class="block aspect-video overflow-hidden">
                            <img src="@post.ImageUrl" alt="@post.ImageAlt" loading="lazy" class="h-full w-full object-cover transition duration-300 group-hover:scale-105" />
                        </a>
                    }
                    <div class="flex flex-1 flex-col p-6">
                        <time datetime="@post.PublishDate.ToString("yyyy-MM-dd")" class="text-sm text-slate-500">@post.PublishDate.ToString("d MMMM yyyy")</time>
                        <h3 class="mt-2 text-xl font-semibold text-slate-900">
                            <a href="@post.Url" class="hover:text-indigo-600">@post.Title</a>
                        </h3>
                        @if (!string.IsNullOrEmpty(post.TeaserText))
                        {
                            <p class="mt-3 flex-1 text-slate-600">@post.TeaserText</p>
                        }
                        <a href="@post.Url" class="mt-5 text-sm font-semibold text-indigo-600 hover:text-indigo-500">Read the post &rarr;</a>
                    </div>
                </article>
            }
        </div>
    }
</section>

