/* Block grid layout: the markup from Views/Partials/blockgrid/ exposes column spans as CSS variables. */
@layer components {
    .umb-block-grid__layout-container {
        display: grid;
        grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
        gap: 3rem 2rem;
    }

    .umb-block-grid__layout-item {
        grid-column: span var(--umb-block-grid--grid-columns, 12) / span var(--umb-block-grid--grid-columns, 12);
    }

    @media (min-width: 48rem) {
        .umb-block-grid__layout-item {
            grid-column: span var(--umb-block-grid--item-column-span) / span var(--umb-block-grid--item-column-span);
        }
    }

    /* Rich text block output (Tiptap markup). */
    .rich-text {
        @apply text-lg leading-relaxed text-slate-700;
    }
    .rich-text > * + * {
        @apply mt-5;
    }
    .rich-text h2 {
        @apply mt-10 text-3xl font-bold tracking-tight text-slate-900;
    }
    .rich-text h3 {
        @apply mt-8 text-2xl font-semibold text-slate-900;
    }
    .rich-text a {
        @apply font-medium text-indigo-600 underline hover:text-indigo-500;
    }
    .rich-text strong {
        @apply font-semibold text-slate-900;
    }
    .rich-text ul {
        @apply list-disc space-y-2 pl-6;
    }
    .rich-text ol {
        @apply list-decimal space-y-2 pl-6;
    }
    .rich-text > :first-child {
        @apply mt-0;
    }
}

